import{_ as i,l as r,o as e,c as l,v as t,p as s,x as n,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"理性疏忽","description":"","frontmatter":{"title":"理性疏忽","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rational-inattention.md","filePath":"econ/rational-inattention.md","lastUpdated":1789023840000}'),E={name:"econ/rational-inattention.md"};function h(c,a,A,_,B,f){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="理性疏忽" tabindex="-1">理性疏忽 <a class="header-anchor" href="#理性疏忽" aria-label="Permalink to &quot;理性疏忽&quot;">​</a></h1><div class="epigraph"><p>注意力是有限信道；最优编码使人对重要、易变的变量反应更灵敏，对其余变量近乎不更新。</p><footer>—— Sims, Implications of Rational Inattention, JME 2003；Maćkowiak and Wiederholt, Optimal Sticky Prices under Rational Inattention, AER 2009</footer></div><p><a href="/econ/sticky-information">上一课</a>的 \\(\\lambda\\) 是外生更新率。本课缺口是<strong>内生注意力</strong>：Shannon 容量下的最优信号。不把 \\(\\lambda\\) 再估一遍，不写神经网络注意力层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sims：人不是每期免费看见状态，而是选择一个关于状态的信号，互信息受容量约束。结果：对小的、不重要的冲击几乎不反应，对大的冲击反应；预测误差与宏观惯性内生。Maćkowiak–Wiederholt：企业把有限注意力在总需求与特异需求之间分配，加总价格对货币更粘、对特异更灵活——与微观价格频繁改动、宏观通胀惯性可并存。缺口是把粘性信息的外生 \\(\\lambda\\) 换成最优信道，而不是再写一次 vintage 加权。</p><p><span class="marginnote">Sims, <em>JME</em> 2003。Maćkowiak and Wiederholt, <em>AER</em> 2009。Woodford 的不完全信息定价。Caplin、Dean、Angeletos 等后续。Shannon 是常用的tractable 约束，不是唯一认知模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代理人最大化效用减注意力成本（或受 \\(I(X;S)\\le\\kappa\\)）。高斯二次时线性信号最优，Kalman 增益由容量决定。宏观：容量 \\(\\kappa\\) 校准到调查误差或 IRF。政策：更嘈杂的政策规则浪费容量，透明规则节省注意力——接到沟通课。与 HANK：穷人可能把容量全用在流动性，不跟踪利率路径，直接欧拉通道更弱。</p>',8)),(e(),s(m,null,{default:n(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KAP%5B%22%E5%AE%B9%E9%87%8F%20%CE%BA%22%5D%20--%3E%20SIG%5B%22%E6%9C%80%E4%BC%98%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20SIG%20--%3E%20GAIN%5B%22%E5%AF%B9%E9%87%8D%E8%A6%81%E5%86%B2%E5%87%BB%E9%AB%98%E5%A2%9E%E7%9B%8A%22%5D%0A%20%20GAIN%20--%3E%20MICRO%5B%22%E5%BE%AE%E8%A7%82%E5%8F%AF%E7%81%B5%E6%B4%BB%22%5D%0A%20%20GAIN%20--%3E%20MACRO%5B%22%E5%AE%8F%E8%A7%82%E5%AF%B9%E6%80%BB%E9%87%8F%E6%9B%B4%E7%B2%98%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与学习：疏忽是每期最优压缩；学习是参数递推。与诊断性：疏忽是噪声，诊断性是偏误（后课）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是稀缺注意力的配置。价格系统若已充分统计，本可节省注意力（Hayek）；一旦价格嘈杂或策略互补强（美容竞赛），每人仍须浪费容量猜别人——Angeletos–La’O、Morris–Shin 的高阶信念接口。本课程不重写<a href="/econ/beauty-contest-higher-order">美容竞赛</a>全文，只借用：疏忽加策略互补 ⇒ 更大惯性。</p><p>容量随激励变：高通胀时人更跟踪 CPI（经验上预期更「解锚」前的更新），这是后课锚定的微观基础之一。</p><p><span class="marginnote">本课不把信息论当宏观的第一性原理重讲。互信息是约束的方便写法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定 \\(\\kappa\\) 的生理值。不把菜单成本与疏忽混成一个参数。资产定价里的疏忽（对新闻反应不足）可点名，不估计横截面。Transformer 与机器学习注意力禁止写入本栏。</p><p>后课默认：更新率可以是最优注意力配置的结果。下一课：偏差不是噪声，而是对新闻的过度反应——诊断性预期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>理性疏忽：容量约束下的最优信号。</li><li>可同时解释微观灵活与宏观惯性。</li><li>与外生 \\(\\lambda\\)、与学习、与认知偏差分列。</li><li>出处：Sims, <em>JME</em> 2003；Maćkowiak and Wiederholt, <em>AER</em> 2009。</li></ul>',10))])}const S=i(E,[["render",h]]);export{u as __pageData,S as default};
